<template><div class="desk"><div class="page-head"><div><h2>在线咨询</h2><p class="sub">查看患者问题并回复。</p></div><button class="secondary" @click="load">↻ 刷新</button></div><div class="desk-grid"><section class="panel"><h3>咨询列表</h3><p v-if="!threads.length" class="muted">暂无咨询记录</p><button class="thread" v-for="t in threads" :key="t.consultationId" @click="open(t.consultationId)"><strong>{{t.realName}} · 咨询 #{{t.consultationId}}</strong><small>{{t.status==='WAITING'?'等待回复':'已回复'}} · {{t.orderId?'报告 #'+t.orderId:'健康咨询'}}</small></button></section><section class="panel"><template v-if="active"><h3>咨询 #{{active.consultationId}}</h3><p class="sub">{{active.status==='WAITING'?'等待回复':'已回复'}} <button v-if="active.orderId" class="link" @click="$router.push({name:'ordersContent',query:{orderId:active.orderId}})">查看关联报告 #{{active.orderId}} →</button></p><div class="messages"><div v-for="m in messages" :key="m.messageId" class="message"><strong>{{m.senderType==='USER'?'患者':'医生'}}</strong><small>{{format(m.createdAt)}}</small><p>{{m.content}}</p></div></div><form @submit.prevent="reply"><label>回复内容<textarea v-model.trim="text" required maxlength="1000" rows="5" placeholder="填写回复"></textarea></label><button class="primary" :disabled="busy">{{busy?'发送中…':'发送回复'}}</button></form></template><p v-else class="muted">请选择一条咨询。</p><p v-if="error" class="error" role="alert">{{error}}</p></section></div></div></template>
<script setup>
import {ref,onMounted} from 'vue'
import {useRouter} from 'vue-router'
import axios from 'axios'
const router=useRouter(),threads=ref([]),active=ref(null),messages=ref([]),text=ref(''),error=ref(''),busy=ref(false)
const api=axios.create({baseURL:'/tijiancms',timeout:10000})
async function call(p,d={}){try{return (await api.post('/consultations/'+p,d)).data}catch(e){if(e.response?.status===401){sessionStorage.removeItem('tijianDoctor');router.replace('/login');window.location.reload()}throw e}}
const format=s=>String(s||'').replace('T',' ').slice(0,16)
async function load(){try{threads.value=await call('list')}catch(e){error.value='咨询列表加载失败。'}}
async function open(id){try{const d=await call('messages',{consultationId:id});active.value=d.consultation;messages.value=d.messages;error.value=''}catch(e){error.value='咨询加载失败。'}}
async function reply(){if(!text.value||busy.value)return;busy.value=true;try{await call('send',{consultationId:active.value.consultationId,content:text.value});text.value='';await open(active.value.consultationId);await load()}catch(e){error.value='回复未发送，请稍后重试。'}finally{busy.value=false}}
onMounted(load)
</script>
<style scoped>.desk-grid{display:grid;grid-template-columns:320px 1fr;gap:18px}.desk-grid section{padding:24px}.desk-grid h3{margin-bottom:14px}.thread{display:block;width:100%;text-align:left;border:0;border-radius:8px;background:#f3f8f6;color:#284c46;padding:14px;margin:10px 0}.thread small{display:block;color:#7c9790;margin-top:6px}.messages{max-height:400px;overflow:auto}.message{background:#f4f8f6;border-radius:8px;padding:14px;margin:12px 0;white-space:pre-wrap;overflow-wrap:anywhere}.message small{color:#8ca39d;margin-left:12px}.message p{margin-top:8px;line-height:1.6}.desk form{display:grid;gap:12px;margin-top:20px}.desk form button{justify-self:start}@media(max-width:750px){.desk-grid{grid-template-columns:1fr}}</style>